// https://www.shadertoy.com/view/MdsXWM
// Audio Eclipse by Airtight

uniform sampler2D waveTexture;

const float dots = 40.;
const float radius = .25;
const float brightness = 0.02;

//convert HSV to RGB
vec3 hsv2rgb(vec3 c){
    vec4 K = vec4(1.0, 2.0 / 3.0, 1.0 / 3.0, 3.0);
    vec3 p = abs(fract(c.xxx + K.xyz) * 6.0 - K.www);
    return c.z * mix(K.xxx, clamp(p - K.xxx, 0.0, 1.0), c.y);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord ) {

	vec2 p=(fragCoord.xy-.5*iResolution.xy)/min(iResolution.x,iResolution.y);
    vec3 c=vec3(0,0,0.1); //background color

    for(float i=0.;i<dots; i++){
		float vol =  texture(waveTexture, vec2(i/dots, 0.0)).x;
		float b = vol * brightness;

		//get location of dot
        float x = radius*cos(2.*3.14*float(i)/dots);
        float y = radius*sin(2.*3.14*float(i)/dots);
        vec2 o = vec2(x,y);

		//get color of dot based on its index in the 
		//circle + time to rotate colors
		vec3 dotCol = hsv2rgb(vec3((i + iTime*10.)/dots,1.,1.0));

        //get brightness of this pixel based on distance to dot
		c += b/(length(p-o))*dotCol;
    }

    //black circle overlay	   
	float dist = distance(p , vec2(0));  
	c = c * smoothstep(0.26, 0.28, dist);

	fragColor = vec4(c,1);
}

function setup() {
  createCanvas(252, 164)
  pixelDensity(4)
}

function draw() {
  clear()

  const waveform = fft().a
  const spectrum = fft({type: 'freq'}).a
  if (!waveform || !spectrum) return

  const sl = spectrum.length / 5

  noStroke();
  for (let i = 0; i< sl; i++){
    let x = map(i, 0, sl, 0, width);
    let h = map(spectrum[i], 0, 250, height, 0) - height;
      fill(255, spectrum[i], 100);
    rect(x, height, width / sl, h)
  }

  noFill();
  beginShape();
  stroke('white');
  strokeWeight(1)
  for (let i = 0; i < waveform.length; i++){
    let x = map(i, 0, waveform.length, 0, width);
    let y = map( waveform[i], 0, 120, 0, height) - 80;
    vertex(x,y);
  }
  endShape();
}
